// 유럽 권역 (DESIGN.md §5.2, 층 8): 유럽 나라(1789~1914 뼈대)와 러시아 제국·소련·러시아 연방의 도형과 versions. 짝 entities 파일: data/entities/europe.yaml
// 가져와도 되는 것: lib.mjs, shared.mjs, areas/korea.mjs, areas/inner-asia.mjs, areas/china.mjs (러시아가 청·조선·외몽골을 뺀다)
// 2026-10-01 (작업 E1): 영국·프랑스·러시아 제국·소련·러시아 연방을 west 권역에서 옮겼다(나라 id는 그대로).
// 2026-10-02 (작업 E2): 1815년(빈 회의)부터 1914년 7월(1차 대전 직전)까지 유럽 권역(조각 domain, 튀르키예·캅카스 포함)의 나라를 넣었다.
//   1815~1914년 영토는 아래 '1815~1914 조각 소유표' 한곳에서 정한다: 조각(또는 선으로 나눈 조각)마다 [해, 나라] 목록을 적고, 나라별 버전은 이 표에서 만든다.
//   한 조각은 표에 한 번만 나오므로 같은 기간 한 조각을 두 나라가 가질 수 없고, 조각을 두 번 쓰거나 빠뜨리면 멈춘다.
//   영국·프랑스·러시아 제국의 1815~1914년 버전도 이 표에서 만든다(E1 버전과 도형이 같음, compare:geo로 확인). 러시아 제국은 1815~1860년 버전을 더했다.
// 2026-10-02 (작업 E3): 1789년(프랑스 혁명)부터 1814년(빈 회의 전)까지를 '1789~1814 조각 소유표'로 더했다. 소유표는 시대마다 하나이고(아래 '조각 소유표의 틀'),
//   1814년과 1815년의 단위 목록이 같은 나라는 한 버전으로 이어진다. 영국·프랑스·러시아 제국도 1789년부터 이 표에서 만든다.
// 2026-10-03 (작업 B1): 1918년(1차 대전 뒤 신생국)부터 1945년(2차 대전 종전 직후)까지를 '1918~1945 조각 소유표'(T1918)로 더했다. E2 표는 1917년까지로 늘렸다(1915년 키프로스만 바뀜).
//   1차 대전 중(1914~1918)의 전시 점령은 그리지 않고(법적 국경), 2차 대전(1939~1945)의 점령지는 중일 전쟁 점령지처럼 점령 항목(occupied_by)으로 그해 말 모습을 그린다.
//   소련의 유럽 쪽(1918~1945)도 이 표에서 만든다(E1의 1921년 무렵 고정 도형 SU_EU_1921을 대신함).
// 2026-10-03 (작업 B2): 1946년부터 1991년(냉전, 소련 해체 직전)까지를 '1946~1991 조각 소유표'(T1946)로 더했다. 소련의 유럽 쪽 1946~1991년도 이 표에서 만든다
//   (E1의 고정 도형 SU_EU_1946을 대신함, 1946~1990년 땅은 같음).
// 2026-10-04 (작업 A): 1992년(소련·유고슬라비아 해체 뒤)부터 지금까지를 '1992~현재 조각 소유표'(T1992)로 더했다. 분쟁·실효 지배 지역(크림·돈바스·트란스니스트리아·압하지야·
//   남오세티야·나고르노카라바흐·코소보)은 법적 주인 색의 지역 항목으로 떼어 내고(기준은 그 표의 머리 주석), 러시아 연방의 땅도 이 표가 정한다(도형은 E1의 RF_EU 그대로).
// 2026-10-06 (작업 D1): 1700년(대북방 전쟁·에스파냐 왕위 계승 전쟁)부터 1788년(프랑스 혁명 전)까지를 '1700~1788 조각 소유표'(T1700)로 더했다. 1789~1814 표와 다르게 나눈 조각을 쓰는 나라
//   (러시아·프로이센·폴란드-리투아니아·오스만)는 1788년과 1789년의 땅이 같으면 뒤 버전의 단위 목록으로 잇는다(LATER_LIST_SEAMS, 1789년부터의 도형이 그대로). 러시아 차르국(1700~1720)도 러시아 제국과 같은 손 도형을 쓴다.
// 유럽 쪽 모양은 행정구역 조각(lib.mjs의 loadFragments('europe'))을 그 시기 국경에 맞춰 묶어 만든다. 권역 바깥선(domain) 밖(시베리아·중앙아시아·극동)은
// west에서 쓰던 손 도형을 그대로 쓴다: 러시아 = D(손 도형, domain) ∪ F(그때 러시아에 속한 조각). 두 경계가 한 자료(domain의 arc)에서 나오므로 틈이 생기지 않는다.
// 오스만 제국은 권역 바깥선 안(발칸·아나톨리아·키프로스·캅카스 일부)만 그린다. 중동·북아프리카는 아직 어느 권역에도 없다.
// 조각은 현대 행정구역이라 역사 경계와 다른 곳은 이름 붙은 선(아래 '조각을 가르는 선')으로 쪼갠다. 근거는 줄마다 적는다.
// 대략 1만 km²보다 작은 차이는 쪼개지 않고 근사로 두었다(아래 '쪼개지 않은 근사' 목록).
import { D, I, U, bx, ring, loadFragments, prefetch } from '../lib.mjs';
import { KWANTUNG, L_AMUR, L_KHASAN, L_USSURI, PRIMORYE, SAKHALIN_S, TAIWAN, TUMEN_SEA } from '../shared.mjs';
import { JOSEON_1449 } from './korea.mjs';
import { ET_NORTH, MN_SW, OUTER_MONGOLIA } from './inner-asia.mjs';
import { QING_BASE } from './china.mjs';

export const source = '유럽 쪽은 Natural Earth 1:10m admin-1(v5.1.2) 현대 행정구역 조각을 그 시기 국경에 맞춰 묶고, 조각이 역사 경계와 다른 곳은 선을 그어 나눈 근사. 유럽 밖(시베리아·중앙아시아·극동)은 대략적인 추정. 운영자 검수 필요';

// ── 행정구역 조각 ─────────────────────────────────────────
const EU = loadFragments('europe');
const { F, domain } = EU;

// adm0(Natural Earth 나라 코드)별 조각 id
const idsOf = (...adm0s) => EU.ids.filter((id) => adm0s.includes(EU.props.get(id).adm0));
// ids에서 빼기. 빼려는 id가 목록에 없으면 멈춘다(조각 id 오타를 잡는다)
const minus = (ids, ...out) => {
  for (const id of out) if (!ids.includes(id)) throw new Error(`europe.mjs: 빼려는 조각 ${id}가 목록에 없음`);
  return ids.filter((id) => !out.includes(id));
};
// 아라스강 남쪽 이란 북서부(아제르바이잔·나흐치반·아르메니아 남쪽): 권역 바깥선 밖의 이 땅은 모두 이란(카자르)이다. 러시아 손 도형의 남쪽 변
// (48.9, 38.4)~(46.0, 38.9)~(44.8, 39.7)이 아라스강보다 남쪽이라 무간 평원·마쿠 쪽 이란 땅 약 1.2만km²가 러시아·소련에 들어가던 것을
// 조각으로 바꾼 아제르바이잔 국경과 맞닿게 잘라 낸다 (2026-10-01, 접합부 쐐기). 권역 바깥선 안쪽은 조각이 정하므로 상자가 그쪽을 덮어도 상관없다
