// 권역 바깥선 밖만 남기기 (손 도형의 시베리아·중앙아시아·극동 쪽). 이란 북서부는 위 상자로 뺀다
const outside = (multi) => D(multi, domain, [IRAN_NW]);

// ── 조각을 가르는 선 ───────────────────────────────────────
