// 드르웽차강(골루프·브로드니차는 프로이센) → 비스와강(토룬은 프로이센, 니에샤바·치에호치네크는 러시아) → 알렉산드루프 쿠야프스키(러시아 국경역)·이노브로츠와프(프로이센) 사이
