// → 브리니차강(소스노비에츠·벵진은 러시아, 카토비체·미스워비체는 프로이센) → 세 황제 모서리(미스워비체) → 올쿠시·스카와(러시아)와 크라쿠프(오스트리아) 사이 → 비스와강.
