const TH = split('DE-TH', ['DE-TH'], [['프로이센', [THURINGIA_PR]]], '튀링겐');
const RP = split('DE-RP', ['DE-RP'], [['팔츠·라인헤센', [PFALZ]], ['나사우', [NASSAU_RP]]], '프로이센');
