// 뤼베크 자유시(LUBECK, 아래 E3 선)는 2026-10-02(작업 E3)에 홀슈타인에서 떼어 독일 연방 국가들 → 북독일 연방 → 독일 제국으로 고쳤다(전에는 홀슈타인과 함께 덴마크로 나옴)
const SH = split('DE-SH', ['DE-SH'], [['슐레스비히', [SCHLESWIG]], ['라우엔부르크', [LAUENBURG]], ['뤼베크', [LUBECK]]], '홀슈타인');
// 폴란드 쪽 네 주(쿠야비아-포모제·대폴란드·슐레지엔·소폴란드): 러시아(의회 왕국) → 크라쿠프 자유시 → 오스트리아 → 나머지 프로이센 차례로 자른다
const PL4 = split('폴란드 4주', ['PL-KP', 'PL-WP', 'PL-SL', 'PL-MA'], [['러시아', [CONGRESS]], ['크라쿠프', [KRAKOW]], ['오스트리아', [GALICIA_W]]], '프로이센');
