own([SH.슐레스비히, SH.라우엔부르크, DK83.북슐레스비히], [[1815, 'denmark'], [1864, 'prussia'], [1866, 'north-german-confederation'], [1871, 'german-empire']]);
own([SH.홀슈타인], [[1815, 'denmark'], [1864, 'austria'], [1866, 'north-german-confederation'], [1871, 'german-empire']]);

