  const PLC = 'polish-lithuanian-commonwealth';
  const DUCHY = 'duchy-of-warsaw';
  const CIS = 'cisalpine-republic'; // 1805년부터 'italy-napoleonic'(renames)
  const NIT = 'italy-napoleonic';
  const GS = 'german-states'; // 1814년: 라인 동맹이 무너진 뒤 빈 회의 전의 독일 나라들(E2의 독일 연방 국가들 묶음을 한 해 앞당김)

  // 서유럽 ─────────────────────────────────────────
  // 영국: 1801년 연합법 전은 그레이트브리튼 왕국(uk 항목, 잉글랜드·스코틀랜드·웨일스와 왕실령)과 아일랜드 왕국(북아일랜드 포함)
