  // 1814년: 사르데냐 왕국 복귀(제노바는 1814년 12월 빈 회의 결정, 1815년 1월 병합), 롬바르디아·베네치아는 오스트리아, 토스카나·파르마·모데나·루카는 E2의 중부 이탈리아 공국들 묶음,
  // 교황 복귀(로마·움브리아·라치오. 로마냐는 1815년까지 오스트리아, 마르케는 뮈라가 다스려 그쪽으로 둠), 나폴리는 1815년 5월까지 뮈라.
