//  2024~2025년 우크라이나군의 쿠르스크주 진입(약 1,000km²), 리만·코스티안티니우카 같은 접전 도시(전선 위에 둠), 체첸(위 ④), 코소보 북부(세르비아계 지역, 코소보에 둠),
