const PRESENT = 2026; // 지금 해. 이 표는 PRESENT년 말까지 정하고, 마지막 표의 끝까지 이어지는 버전은 to: null(지금까지)로 쓴다
const T1992 = makeTable(1992, PRESENT + 1, { 'fr-yugoslavia': [2003, 'serbia-montenegro'], 'macedonia-republic': [2019, 'north-macedonia'] });
