// ── 소유표 → 버전 ─────────────────────────────────────────
// 표를 시대 순서로 이어 해마다 나라별 단위 목록을 만들고, 같은 목록이 이어지는 기간을 한 버전으로 묶는다(표의 경계를 넘어서도 이어진다)
const TABLES = [T1700, T1789, T1815, T1918, T1946, T1992];
const TABLE_TO = TABLES.at(-1).TO;
const segments = {}; // 나라 → [[from, to, 단위 목록]]
const nullSegments = []; // 주인 없는 단위의 기간
TABLES.forEach((table, i) => {
  if (i && table.FROM !== TABLES[i - 1].TO) throw new Error('europe.mjs: 소유표 기간이 이어지지 않음');
  for (const [year, owner, list] of table.finish()) {
    const segs = owner === null ? nullSegments : (segments[owner] ??= []);
    const last = segs.at(-1);
    if (last && last[1] === year && last[2].join('|') === list.join('|')) last[1] = year + 1;
    else segs.push([year, year + 1, list]);
  }
});

// 단위 목록 → 도형: 통째 조각은 F로 한 번에 합치고(arc 병합), 나눈 조각은 polyclip 합집합으로 더한다. 같은 목록은 한 번만 계산한다
const unitGeom = new Map();
const geomOfUnit = (u) => {
  if (!unitGeom.has(u)) unitGeom.set(u, unitMake.get(u)());
  return unitGeom.get(u);
};
const builtGeom = new Map();
// 단위 목록을 합치는 합집합의 인자. 나눈 조각이 없으면 null(F 하나로 끝남)
const buildArgs = (list) => {
  const ids = list.filter((u) => unitMake.get(u) === null);
  const parts = list.filter((u) => unitMake.get(u) !== null).map(geomOfUnit);
  return parts.length ? [...(ids.length ? [F(...ids)] : []), ...parts] : null;
};
const build = (list) => {
  const key = list.join('|');
  if (!builtGeom.has(key)) {
    const args = buildArgs(list);
    builtGeom.set(key, args ? U(...args) : F(...list));
  }
  return builtGeom.get(key);
};
// 마지막 표(T1992)의 끝(PRESENT년 말)까지 이어지는 버전은 to: null(지금까지)로 쓴다.
// 2026-10-04(작업 A): 전에는 마지막 표의 끝 모습이 이어지는 마지막 해를 나라마다 적었다(TAIL_TO, 작업 E2~B2). 표가 지금까지 늘어 모두 null이 되어 없앴다
// 표가 바뀌는 해에 단위 이름만 바뀌고 땅은 같은 이음매: 앞 버전의 단위 목록으로 잇는다(작업 B1).
// 프랑스는 1918년 표에서 1940년 분계선이 지나는 도를 나눈 단위로 쓰지만 1917년과 땅이 같다(대칭차 0km²)
const SAME_LAND_SEAMS = { france: [1918] };
for (const [id, years] of Object.entries(SAME_LAND_SEAMS)) {
  for (const y of years) {
    const segs = segments[id];
    const i = segs.findIndex(([from]) => from === y);
    if (i < 1 || segs[i - 1][1] !== y) throw new Error(`europe.mjs: ${id}의 ${y}년 이음매가 없음`);
    segs.splice(i - 1, 2, [segs[i - 1][0], segs[i][1], segs[i - 1][2]]);
  }
}
// 반대 방향 이음매(작업 D1): 1700~1788 소유표가 1789~1814 표와 다르게 나눈 조각(잉그리아·1772년 경계·자포리자·헤르손·사마라강·아조프·알레산드리아·모레아·트로이지니아·포모제·서포메른·바르미아)을 쓰는 나라는
// 1788년과 1789년의 땅이 같아도 단위 이름이 달라 버전이 갈린다. 이런 나라는 뒤 버전의 단위 목록으로 이어(1789년부터의 도형이 바이트 단위로 그대로) 앞 버전의 시작 해부터 쓴다.
// 땅이 같은지는 작업 D1에서 이음매를 빼고 만든 두 버전의 대칭차로 확인했다(모두 0km², 결과 노트). 땅이 다른 나라를 여기 넣으면 안 된다
const LATER_LIST_SEAMS = { russia: [1789], prussia: [1789], 'polish-lithuanian-commonwealth': [1789], ottoman: [1789], sardinia: [1789] };
for (const [id, years] of Object.entries(LATER_LIST_SEAMS)) {
  for (const y of years) {
    const segs = segments[id];
    const i = segs.findIndex(([from]) => from === y);
    if (i < 1 || segs[i - 1][1] !== y) throw new Error(`europe.mjs: ${id}의 ${y}년 이음매가 없음`);
    segs.splice(i - 1, 2, [segs[i - 1][0], segs[i][1], segs[i][2]]);
  }
}
const tableVersions = (id) => {
  const segs = segments[id];
  if (!segs) throw new Error(`europe.mjs: 소유표에 ${id}의 땅이 없음`);
  return segs.map(([from, to, list]) => [from, to === TABLE_TO ? null : to, list]);
};

// 소련의 유럽 쪽
// - 1918~1945년(작업 B1): '1918~1945 조각 소유표'에서 만든다(1939~1940 합병, 1941~1944 독일 점령 범위, 1944~1945 되찾은 땅). 동쪽은 손 도형 SOVIET
// - 1946~1991년(작업 B2): '1946~1991 조각 소유표'에서 만든다. 1946~1990년은 지금의 러시아·발트 3국·벨라루스·우크라이나·몰도바·캅카스 3국 조각 전부
//   (칼리닌그라드 1945, 카르파티아 루스 1945, 크림은 1954년부터 우크라이나 SSR이지만 소련 안. E1의 고정 도형 SU_EU_1946과 땅이 같음), 1991년은 발트 3국(나르바 시가지 포함)을 뺀다.
//   동쪽은 손 도형 SOVIET_1946(사할린 남부를 더함. 일본 권역의 사할린 남부가 1946년까지)
// 러시아 연방: 지금의 러시아 조각 가운데 크림·세바스토폴(2014년 러시아 합병 선언, 국제적으로 우크라이나 영토)을 뺀다.
// 2026-10-03(작업 B2): 레닌그라드주 조각이 덮던 나르바 시가지(강 서쪽, 에스토니아)를 NARVA_W로 뺀다
// 2026-10-04(작업 A): 땅은 '1992~현재 조각 소유표'가 정한다(크림·세바스토폴은 2014년까지 우크라이나, 그 뒤 귀속 논쟁 지역이라 러시아 연방 땅이 아님. 도형이 바뀌지 않음).
// 표의 단위 목록이 이 도형과 같은 땅(레닌그라드주의 나르바 선 동쪽 + 나머지 러시아 조각)이고 1992년부터 한 버전인지 확인하고 도형은 이것을 그대로 쓴다
const RF_EU = D(F(...minus(RUS_ALL, 'UA-43', 'UA-40')), [NARVA_W]);
{
  const want = [...minus(RUS_ALL, 'RU-LEN', 'UA-43', 'UA-40'), 'RU-LEN(1946)/레닌그라드'].sort().join('|');
  const segs = tableVersions('russia-fed');
  if (segs.length !== 1 || segs[0][0] !== 1992 || segs[0][1] !== null || segs[0][2].join('|') !== want) throw new Error('europe.mjs: 소유표의 러시아 연방 땅이 RF_EU와 다름');
}

// ── 유럽 밖 손 도형 (west.mjs에서 옮김, 좌표 그대로) ──────────────
