  return cuts.map((from, i) => {
    const to = cuts[i + 1] ?? eu.at(-1)[1];
    const list = eu.filter(([f]) => f <= from).at(-1)[2];
    const east = RUSSIA_EAST.filter(([y]) => y <= from).at(-1)[1];
    return [from, to, east, list];
  });
