// 병렬 미리 계산 (2026-10-03, lib.mjs의 prefetch): 아래 versions·gapZones가 부를 무거운 합집합·차집합을 단계마다 worker들에 나눠 미리 계산해 연산 메모에 넣는다.
// versions·gapZones는 원래 순서대로 같은 연산을 부르고 메모에서 읽으므로 결과는 미리 계산하지 않을 때와 같다(빠뜨린 연산은 그때 계산할 뿐).
// 1단계 단위 목록 합치기(build), 2단계 러시아·소련 손 도형의 바깥 자르기(outside), 3단계 그 둘을 쓰는 합치기와 빈 땅 검사 구역
{
  const lists = [
    ...TABLE_ENTITIES.flatMap((id) => tableVersions(id).map(([, , list]) => list)),
    ...tableVersions('france').filter(([from]) => from !== 1947).map(([, , list]) => list),
    tableVersions('italy').at(-1)[2], ...tableVersions('italy-republic').slice(1).map(([, , list]) => list),
    ...russiaPlan().map(([, , , list]) => list), ...russiaPlan('russia-tsardom').map(([, , , list]) => list), ...sovietPlan().map(([, , , list]) => list),
    ...nullSegments.map(([, , list]) => list),
  ];
  const seen = new Set();
  const jobs = [];
  for (const list of lists) {
    const key = list.join('|');
    if (seen.has(key) || builtGeom.has(key)) continue;
    seen.add(key);
    const args = buildArgs(list);
    if (args) jobs.push(['union', ...args]);
  }
  prefetch(jobs);
  const plans = [...russiaPlan(), ...russiaPlan('russia-tsardom'), ...sovietPlan()];
  const easts = [...new Set(plans.map(([, , east]) => east))];
  prefetch([...easts, RUSSIA_FED].map((m) => ['difference', m, domain, [IRAN_NW]]));
  prefetch([
    ...plans.map(([, , east, list]) => ['union', outsideOf(east), build(list)]),
    ...nullSegments.map(([, , list]) => ['difference', domain, build(list)]),
  ]);
}

// 나라 id: [[from, to, 멀티폴리곤, 확실성?], ...]. to가 null이면 지금까지, 확실성은 'disputed' 등(없으면 'estimated').
// 출처(geojson의 source)는 이 권역의 source
// 영국은 1707~1800 그레이트브리튼 왕국(1700~1706년은 잉글랜드·스코틀랜드 항목, 작업 D1), 1801~1921 아일랜드를 합친 연합 왕국, 1922년부터 아일랜드 자유국을 뺀 모습으로 모두 소유표에서 만든다(작업 B1, 전에는 1922년 버전이 E1 도형 UK_1922. 조각 묶음이 같아 도형도 같음)
export const versions = {
  'russia-tsardom': withEast(russiaPlan('russia-tsardom')),
  russia: withEast(russiaPlan()),
  'soviet-union': withEast(sovietPlan()),
  'russia-fed': [[1992, null, U(outside(RUSSIA_FED), RF_EU)]],
  france: tableVersions('france').map(([from, to, list], i, all) => {
    if (i === all.length - 1 && (from !== 1947 || to !== null)) throw new Error('europe.mjs: 프랑스의 마지막 버전이 1947~이 아님');
    return [from, to, from === 1947 ? U(FRANCE_1947, geomOfUnit(IT_IM.망통)) : build(list)];
  }),
  // 이탈리아 공화국: 1946년 6월 국민 투표로 왕국이 공화국으로 바뀜(이름만 바뀜, 땅은 1945년 말과 같음). 1946년 버전은 B1처럼 왕국의 1945년 단위 목록으로 만들고(같은 땅),
  // 1947년(파리 강화 조약)부터는 소유표(작업 B2)
  'italy-republic': tableVersions('italy-republic').map(([from, to, list], i) => {
    if (i === 0 && (from !== 1946 || to !== 1947)) throw new Error('europe.mjs: 이탈리아 공화국의 첫 버전이 1946~1947이 아님');
    return [from, to, build(i === 0 ? tableVersions('italy').at(-1)[2] : list)];
  }),
  ...Object.fromEntries(TABLE_ENTITIES.map((id) => [id, tableVersions(id).map(([from, to, list]) => [from, to, build(list), ...(DISPUTED.has(id) ? ['disputed'] : [])])])),
};

// 빈 땅 검사 구역 (DESIGN.md §5.4): 권역 바깥선(domain, 모든 조각의 합)에서 그해 주인 없는 단위(소유표의 null)를 뺀 곳.
// 주인 없는 단위가 같은 기간마다 구역 하나. 1700년부터 지금까지(뼈대를 채운 구간, 2026-10-02 작업 E3에서 1789년까지, 2026-10-03 작업 B1에서 1945년까지, 같은 날 작업 B2에서 1991년까지,
// 작업 A에서 지금까지, 2026-10-06 작업 D1에서 1700년까지 넓힘)만 검사한다. 시작 해는 가장 이른 소유표의 첫 해(TABLES[0].FROM)라 표를 더하면 따라 넓어진다.
// 마지막 구역은 끝이 없다(to: null, 지금 뒤의 해도 검사).
// 일부러 비워 둔 곳: 스발바르(1925년까지 무주지)·얀마옌(1929년까지 무주지), 프란츠요제프 제도(1926년까지 무주지),
// 에리반·나흐치반 칸국과 수르말루(1828년까지 페르시아). 1789~1814년(작업 E3)에 더: 몰타(1799년까지: 1798년까지 몰타 기사단령, 1798~1799 프랑스군이 발레타에 갇힘),
// 러시아에 합쳐지기 전의 조지아 왕국들(카르틀리-카헤티 1801년까지, 서조지아 1810년까지)과 아제르바이잔·다게스탄의 칸국들·아르메니아 북부(1806년까지, 페르시아 종주).
// 1700~1788년(작업 D1)에 더: 1773년까지 카바르다·체첸·잉구시·북오세티야. 동조지아·아르메니아·아제르바이잔은 1724~1734년(오스만·러시아)을 빼고 비워 둔다
// 1918~1938년(작업 B1)에 더: 하타이(프랑스 위임 통치령 시리아).
// 2026-10-04(운영자 승인): 영국 식민지(지브롤터·몰타 1800~1963·키프로스 1915~1959·영국 주권 기지 지역 1960~)를 영국 땅으로 칠해 더는 비우지 않는다.
// 그래서 1939년부터는 주인 없는 단위가 없다. 주인 없는 단위가 없는 해도 권역 바깥선 전체를 구역으로 검사한다(마지막 구역 '유럽 1939~'는 끝이 없음)
const gapSegments = [];
for (let year = TABLES[0].FROM; year < TABLE_TO; year++) {
  const list = nullSegments.find(([from, to]) => from <= year && year < to)?.[2] ?? [];
  const last = gapSegments.at(-1);
  if (last && last[1] === year && last[2].join('|') === list.join('|')) last[1] = year + 1;
  else gapSegments.push([year, year + 1, list]);
}
export const gapZones = gapSegments.map(([from, to, list]) => {
  const open = to === TABLE_TO;
  return { name: open ? `유럽 ${from}~` : `유럽 ${from}~${to - 1}`, zone: list.length ? D(domain, build(list)) : domain, from, to: open ? null : to };
});
